{
  "findings": [
    {
      "check_id": "CKV_AWS_45",
      "title": "Lambda permission lacks source ARN restriction",
      "resource": "aws_lambda_permission.api_gateway_invoke",
      "severity": "HIGH",
      "explanation": "The Lambda permission allows invocation from any API Gateway without restricting the source ARN, potentially allowing unauthorized invocation."
    }
  ],
  "patched_code": "resource \"aws_lambda_permission\" \"api_gateway_invoke\" {\n  statement_id  = \"AllowExecutionFromAPIGateway\"\n  action        = \"lambda:InvokeFunction\"\n  function_name = aws_lambda_function.log_processing_pipeline.function_name\n  principal     = \"apigateway.amazonaws.com\"\n  source_arn = \"${aws_api_gateway_rest_api.log_processing_api.execution_arn}/*/*\"\n}",
  "fix_summary": "Added source ARN restriction to the Lambda permission to limit invocation to a specific API Gateway."
}
